const GOAL = 12;
export default {
  title: "Bounds Check",
  dek: "Stop each base64 write inside the safe zone before it overflows the buffer.",
  width: 240,
  height: 160,
  controls: { layout: "a", a: "ASSERT", hint: "Space / Z or tap ASSERT to stop the write" },
  howToPlay: {
    summary: "You are the length check in EVP_EncodeBlock(). Stop every write inside the green safe zone.",
    steps: [
      "Bytes stream into the buffer. Press ASSERT while the fill is inside the green zone.",
      "Stopping short or letting it run past the buffer end costs a life. You have three.",
      "Writes speed up, zones shrink and later inputs surge. Patch 12 writes to win.",
    ],
    controls: "Space / Z or the ASSERT button",
  },
  init(g) {
    g.state = {
      lives: 3, done: 0, combo: 0, phase: "wait", timer: 0.5,
      p: 0, speed: 0.5, z0: 0.7, zw: 0.16, surge: 0, wob: 0, msg: "", msgCol: "white",
      stopAt: -1, bytes: [],
    };
    g.score = 0;
  },
  newRound(g) {
    const s = g.state, lvl = s.done;
    s.p = 0; s.stopAt = -1;
    s.speed = 0.5 + lvl * 0.06 + g.rand(0, 0.08);
    s.zw = Math.max(0.075, 0.17 - lvl * 0.009);
    s.z0 = g.rand(0.45, 0.97 - s.zw);
    s.surge = lvl >= 4 ? g.rand(0.6, 1.2) : 0;
    s.wob = lvl >= 8 ? g.rand(0, 6.28) : -1;
    s.phase = "fill";
  },
  fail(g, why) {
    const s = g.state;
    s.lives--; s.combo = 0; s.phase = "result"; s.timer = 0.8;
    s.msg = why; s.msgCol = "danger";
    g.sfx("hit"); g.shake(4, 0.25); g.flash("#ff0000", 0.08);
    g.particles(20 + Math.min(s.p, 1.05) * 200, 70, "danger", 14);
    if (s.lives <= 0) g.lose(`Buffer overflowed. Patched ${s.done}/${GOAL} writes.`);
  },
  update(g, dt) {
    const s = g.state;
    if (s.phase === "wait" || s.phase === "result") {
      s.timer -= dt;
      if (s.timer <= 0) this.newRound(g);
    } else if (s.phase === "fill") {
      let v = s.speed;
      if (s.surge && s.p > 0.3) v *= 1 + s.surge * Math.min(1, (s.p - 0.3) * 3);
      if (s.wob >= 0) v *= 0.75 + 0.5 * Math.abs(Math.sin(g.t * 5 + s.wob));
      s.p += v * dt;
      if (g.tick % 3 === 0) s.bytes.push({ x: 20, y: 64 + g.randInt(0, 12), v: 60 + g.rand(0, 40), l: 0.6 });
      if (g.pressed("a")) {
        s.stopAt = s.p;
        if (s.p >= s.z0 && s.p <= s.z0 + s.zw) {
          s.done++; s.combo++;
          const mid = s.z0 + s.zw / 2, acc = 1 - Math.abs(s.p - mid) / (s.zw / 2);
          const pts = 100 + Math.round(acc * 50) + (s.combo - 1) * 20;
          g.score += pts;
          s.msg = acc > 0.7 ? `PERFECT +${pts}` : `PATCHED +${pts}`; s.msgCol = "ok";
          s.phase = "result"; s.timer = 0.6;
          g.sfx("coin"); g.particles(20 + s.p * 200, 70, "gaming", 12);
          if (s.done >= GOAL) g.win(`All ${GOAL} writes bounded. Score ${g.score}.`);
        } else if (s.p < s.z0) this.fail(g, "SHORT WRITE");
        else this.fail(g, "LATE ASSERT");
      } else if (s.p >= 1) { s.p = 1.02; this.fail(g, "OVERFLOW"); }
    }
    for (const b of s.bytes) { b.x += b.v * dt; b.l -= dt; }
    s.bytes = s.bytes.filter((b) => b.l > 0 && b.x < 20 + s.p * 200);
    g.hud(`Patched ${s.done}/${GOAL} · ${"♥".repeat(Math.max(0, s.lives))}${s.combo > 1 ? " · x" + s.combo : ""}`);
  },
  draw(g) {
    const s = g.state;
    g.cls("dark");
    g.txt("EVP_EncodeBlock(out, in, len)", 120, 22, { color: "tech", size: 8, align: "center" });
    g.txt("CVE-2026-121481", 120, 34, { color: "muted", size: 7, align: "center" });
    // buffer frame
    g.rect(18, 58, 204, 28, "panel", "rule");
    for (let i = 1; i < 16; i++) g.line(20 + i * 12.5, 60, 20 + i * 12.5, 84, "rgba(255,255,255,0.06)");
    // safe zone
    const zx = 20 + s.z0 * 200, zw = s.zw * 200;
    g.rect(zx, 60, zw, 24, "rgba(34,197,94,0.28)", "gaming");
    // fill
    const pf = Math.min(s.p, 1.05);
    const col = s.p > s.z0 + s.zw ? "danger" : s.p >= s.z0 ? "gaming" : "tech";
    if (pf > 0) g.rect(20, 63, Math.min(pf, 1) * 200, 18, col);
    if (s.p > 1) g.rect(220, 63, (pf - 1) * 200, 18, "danger");
    for (const b of s.bytes) g.rect(b.x, b.y, 2, 2, "white");
    // buffer end
    g.line(220, 52, 220, 92, "danger", 2);
    g.txt("END", 220, 96, { color: "danger", size: 7, align: "center" });
    g.txt("SAFE", zx + zw / 2, 50, { color: "gaming", size: 7, align: "center" });
    if (s.stopAt >= 0) g.line(20 + Math.min(s.stopAt, 1.05) * 200, 56, 20 + Math.min(s.stopAt, 1.05) * 200, 88, "white", 2);
    // surge warning
    if (s.phase === "fill" && s.surge && s.p > 0.3 && g.tick % 20 < 10) g.txt("SURGE", 40, 50, { color: "amber", size: 7, align: "center" });
    if (s.phase === "result") g.txt(s.msg, 120, 116, { color: s.msgCol, size: 10, align: "center", bold: true });
    g.bar(20, 140, 200, 6, s.done / GOAL, "gaming", "rule");
    g.txt(`len = ${Math.floor(Math.min(s.p, 1.05) * 96)} / 96`, 120, 128, { color: "muted", size: 7, align: "center" });
  },
};
